 public sealed class Stage58Telemetry:IGeometryTrace,IDisposable
 {
  public readonly double[] Ms=new double[(int)GeometryPhase.Count];public readonly long[] Bytes=new long[(int)GeometryPhase.Count];public readonly int[] Calls=new int[(int)GeometryPhase.Count];
  readonly long[] started=new long[128],allocated=new long[128];int depth;readonly string[] names;public readonly string Output;public readonly bool AllocationCounterValid;public ProfilerRecorder Main,Render,Allocation;readonly FrameTiming[] timing=new FrameTiming[1];
  public Stage58Telemetry(string output){Output=output;Directory.CreateDirectory(output);long probeStart=GC.GetAllocatedBytesForCurrentThread();var probe=new byte[1048576];AllocationCounterValid=GC.GetAllocatedBytesForCurrentThread()-probeStart>=1048576;GC.KeepAlive(probe);names=new string[(int)GeometryPhase.Count];for(int i=0;i<names.Length;i++)names[i]="SG58."+((GeometryPhase)i).ToString();Main=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Main Thread");Render=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Render Thread");Allocation=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame");GeometryTrace.Sink=this;}
  bool Watched(GeometryPhase p)=>p==GeometryPhase.Navigation||p==GeometryPhase.Construction||p==GeometryPhase.MeshBuild||p==GeometryPhase.MeshUpload||p==GeometryPhase.Overlay||p==GeometryPhase.CacheInvalidation||p==GeometryPhase.Visibility;
  public void Begin(GeometryPhase p){if(!Watched(p))return;started[depth]=System.Diagnostics.Stopwatch.GetTimestamp();allocated[depth]=GC.GetAllocatedBytesForCurrentThread();depth++;Profiler.BeginSample(names[(int)p]);}
  public void End(GeometryPhase p){if(!Watched(p))return;Profiler.EndSample();depth--;int i=(int)p;Ms[i]+=(System.Diagnostics.Stopwatch.GetTimestamp()-started[depth])*1000.0/System.Diagnostics.Stopwatch.Frequency;if(AllocationCounterValid)Bytes[i]+=GC.GetAllocatedBytesForCurrentThread()-allocated[depth];else Bytes[i]=-1;Calls[i]++;}
  public void Reset(){Array.Clear(Ms,0,Ms.Length);Array.Clear(Bytes,0,Bytes.Length);Array.Clear(Calls,0,Calls.Length);}
  public void StartCapture(string name){StopCapture();Profiler.logFile=Path.Combine(Output,name+".raw");Profiler.maxUsedMemory=256*1024*1024;Profiler.enableBinaryLog=true;Profiler.enabled=true;}
  public void StopCapture(){Profiler.enabled=false;Profiler.logFile="";}
  public double GpuMs(){FrameTimingManager.CaptureFrameTimings();return FrameTimingManager.GetLatestTimings(1,timing)>0&&timing[0].gpuFrameTime>0?timing[0].gpuFrameTime:-1;}
  public void Dispose(){StopCapture();if(GeometryTrace.Sink==this)GeometryTrace.Sink=null;Main.Dispose();Render.Dispose();Allocation.Dispose();}
 }
 [DefaultExecutionOrder(-2500)]public sealed class Stage58Benchmark:MonoBehaviour
 {
  [Serializable]public class Frame{public int navPending,navProcessed,discoveryKnown;public int frame,counterFrame,resident,pending,presentation,uploads,built,evicted,navCalls,actors,projectiles;public string phase;public double discovery;public double interval,main,render,gpu,nav,construction,overlay,display,sim,navLatency;public long allocation,navBytes;public bool ready;}
