  [Serializable]public class Memory{public string name;public int frame,meshes,materials,resident,buffers;public long managed,unity,meshBytes,materialBytes,processPrivate,workingSet;}
  [Serializable]public class Result{public bool threadAllocationCounterValid;public string error="",hardware,quality,mode,definitionHash;public List<Frame> frames=new List<Frame>(20000);public List<Event> events=new List<Event>();public List<Memory> memory=new List<Memory>();public List<string> checks=new List<string>();}
  public sealed class Agent{public Point2 P,Goal;public List<Point2> Path;public int Cursor;public bool Queued;public double Requested;}
  Stage57Preview camp;Stage58Telemetry telemetry;string output;Result data=new Result();readonly WaitForEndOfFrame end=new WaitForEndOfFrame();readonly List<Agent> agents=new List<Agent>();readonly Queue<Agent> requests=new Queue<Agent>(128);Point2[] projectiles=new Point2[128];double simMs,latency,discoveryMs,nextStressEdit;int projectileCount,lastNavProcessed,stressCursor;CaveDiscovery stressDiscovery;readonly List<DualTile> stressEarth=new List<DualTile>();readonly List<DualTile> editBatch=new List<DualTile>(3);
  System.Collections.IEnumerator Start(){var args=Environment.GetCommandLineArgs();if(Array.IndexOf(args,"-stage58Cave")>=0){UnityEngine.SceneManagement.SceneManager.LoadScene("CaveProfileStage58");yield break;}int n=Array.IndexOf(args,"-stage58Output");if(n<0)yield break;output=args[n+1];Directory.CreateDirectory(output);data.mode=Array.IndexOf(args,"-stage58After")>=0?"after":"baseline";telemetry=new Stage58Telemetry(output);data.threadAllocationCounterValid=telemetry.AllocationCounterValid;telemetry.StartCapture("cold-and-construction");long t=System.Diagnostics.Stopwatch.GetTimestamp();camp=GetComponent<Stage57Preview>();camp.Initialize();EventScope("initialization",t);camp.automation=true;camp.showPanel=false;camp.Live.automation=true;Application.runInBackground=true;Application.targetFrameRate=60;QualitySettings.vSyncCount=0;data.quality=QualitySettings.names[QualitySettings.GetQualityLevel()];data.hardware=SystemInfo.processorType+" / "+SystemInfo.graphicsDeviceName+" / "+SystemInfo.graphicsDeviceType;data.definitionHash=camp.Session.Definition.Fingerprint();camp.Session.Committed+=batch=>data.events.Add(new Event{frame=Time.frameCount,name="geometry:"+batch.Reason,ms=camp.MutationMs,cells=batch.Cells.Count});yield return Settle();MemorySample("cold");camp.Go("fire");yield return Settle();yield return Capture("01-fire-initial");var warmRevisions=new Dictionary<DualTile,int>();foreach(var pair in camp.Live.Stream.Resident)warmRevisions[pair.Key]=pair.Value.Revision;yield return RunPhase("warm-camera",5,0,false);bool stable=true;foreach(var pair in warmRevisions)if(camp.Live.Stream.Resident.TryGetValue(pair.Key,out var chunk)&&chunk.Revision!=pair.Value)stable=false;Check(stable,"Warm retained chunks preserve topology; new residency is separate");telemetry.StopCapture();yield return Snapshot("warm");yield return LocalDigProbes();
   camp.Session.AddBuddy();camp.DigBedrooms();yield return RunConstruction("normal-construction",0,false,60);Check(camp.Session.Established==1,"Normal construction completed");camp.Session.AddBuddy();camp.DigBedrooms();yield return RunConstruction("fast-construction",1,false,30);camp.Session.AddBuddy();camp.DigBedrooms();yield return RunConstruction("very-fast-construction",2,false,20);camp.Session.AddBuddy();camp.DigBedrooms();yield return RunConstruction("finish-current",0,true,20);
   telemetry.StartCapture("build-first-dorm");camp.ConstructionClock.BuildDorm=true;camp.ConstructionClock.BuildTarget=10;yield return RunPhase("build-first-dorm",15,0,true);telemetry.StopCapture();Check(camp.Session.Established==10,"Ten authorized beds completed");yield return Capture("02-fire-ten-beds");MemorySample("construction");camp.Session.BuddyDied();camp.Session.AddBuddy();Check(camp.Session.Residents[camp.Session.Residents.Count-1].Slot==1,"Vacancy reused");camp.Session.Advance();camp.Session.Advance();camp.Session.Recover();
   foreach(var load in new[]{8,32,64}){if(load==64){camp.ResetTest(0);camp.Go("fire");camp.Session.FakeReturn(8,5,2);camp.ConstructionClock.BuildDorm=true;camp.ConstructionClock.BuildTarget=10;camp.Session.Recover();camp.Session.Committed+=batch=>data.events.Add(new Event{frame=Time.frameCount,name="high-geometry:"+batch.Reason,ms=camp.MutationMs,cells=batch.Cells.Count});yield return Settle();}Seed(load);telemetry.StartCapture("load-"+load);yield return RunPhase("load-"+load,20,load,true);telemetry.StopCapture();MemorySample("load-"+load);}
   if(camp.Session.Deaths==0)camp.Session.BuddyDied();camp.Session.Advance();camp.Session.Advance();Seed(8);yield return RunPhase("fixed-area-steady",60,8,true);MemorySample("steady");yield return Snapshot("steady");foreach(var marker in camp.Session.Definition.Markers)if(camp.Session.Active(marker.Gate)){camp.Go(marker.Id);yield return Settle();yield return RunPhase("whole-camp-travel",1,8,true);}camp.Go("fire");yield return Settle();MemorySample("returned");
   for(int i=0;i<3;i++){t=System.Diagnostics.Stopwatch.GetTimestamp();camp.returnBuddies=2;camp.FakeReturn();EventScope("fake-return-"+i,t);yield return Settle();}for(int i=0;i<3;i++){t=System.Diagnostics.Stopwatch.GetTimestamp();camp.ResetTest(0);EventScope("reset-"+i,t);yield return Settle();camp.Go("fire");yield return Settle();MemorySample("reset-"+i);}yield return Snapshot("reset");Check(Type.GetType("GameState, Assembly-CSharp").GetProperty("Instance").GetValue(null)==null,"No GameState registration");Check(Type.GetType("DiggableTerrainService, Assembly-CSharp").GetProperty("Active").GetValue(null)==null,"No production terrain registration");stressDiscovery?.Dispose();File.WriteAllText(Path.Combine(output,"result.json"),JsonUtility.ToJson(data,true));telemetry.Dispose();Application.Quit(data.error==""?0:1);
  }
  System.Collections.IEnumerator RunConstruction(string phase,int speed,bool finish,double timeout){camp.ConstructionClock.Speed=speed;camp.ConstructionClock.FinishCurrent=finish;double start=Time.realtimeSinceStartupAsDouble;while(camp.Constructing&&Time.realtimeSinceStartupAsDouble-start<timeout){telemetry.Reset();double t=Time.realtimeSinceStartupAsDouble;camp.TickResidents(Math.Min(.05,Time.unscaledDeltaTime));yield return end;Record(phase,(Time.realtimeSinceStartupAsDouble-t)*1000);}Check(!camp.Constructing,phase+" completed");}
  System.Collections.IEnumerator RunPhase(string phase,double seconds,int load,bool residents){double start=Time.realtimeSinceStartupAsDouble;int frame=0;while(Time.realtimeSinceStartupAsDouble-start<seconds){telemetry.Reset();double t=Time.realtimeSinceStartupAsDouble;double dt=Math.Min(.05,Time.unscaledDeltaTime);if(residents)camp.TickResidents(dt);if(load>0)Simulate(dt,load,frame);else simMs=0;
    // Camera focus moves through the existing projection; physical player position stays valid.
    var origin=camp.Live.Position;camp.Live.SetPreviewFocus(origin+new Vector2((float)Math.Sin(frame*.02)*3,(float)Math.Cos(frame*.017)*2));yield return end;Record(phase,(Time.realtimeSinceStartupAsDouble-t)*1000);frame++;}}
  System.Collections.IEnumerator LocalDigProbes(){var stand=new Point2(84.5,123.5);Check(camp.Session.Route(camp.Session.Definition.Marker("fire").Interaction,stand,1).Count>0,"Ordinary dig approach connected");camp.Live.Teleport(Stage57Preview.V(stand));yield return Settle();for(int i=0;i<3;i++){long t=System.Diagnostics.Stopwatch.GetTimestamp();int n=camp.Dig(new Point2(camp.Live.Position.x,camp.Live.Position.y+1.6));data.events.Add(new Event{frame=Time.frameCount,name="local-player-dig",ms=StreamingGeometry.Elapsed(t),cells=n});Check(n>0,"Local player dig accepts actual dirt batch "+i);var next=camp.Session.Move(Stage57Preview.P(camp.Live.Position),new Point2(0,1),1);camp.Live.TeleportWithoutFocus(Stage57Preview.V(next));yield return null;}camp.Live.Teleport(new Vector2(84.5f,115.5f));int before=camp.Session.Revision;int changed=camp.Dig(new Point2(84.5,113.5));Check(changed==0&&camp.Session.Revision==before,"Dig near protected Fire preserves station");camp.Go("fire");yield return Settle();}
  void Seed(int count){stressDiscovery?.Dispose();stressDiscovery=null;stressEarth.Clear();stressCursor=0;nextStressEdit=Time.realtimeSinceStartupAsDouble;for(int y=0;y<192;y++)for(int x=0;x<192;x++)if(camp.Session.Definition.Category(x,y)==CampCell.Expansion&&camp.Session.Terrain.IsSolid(x,y))stressEarth.Add(new DualTile(x,y));if(count==64){long t=System.Diagnostics.Stopwatch.GetTimestamp();stressDiscovery=new CaveDiscovery(camp.Session.BindReadOnlyGeometry(),new DiscoveryIndex(camp.Session.BindReadOnlyGeometry(),new DiscoveryRegion[0]));EventScope("stress-discovery-index",t);}agents.Clear();requests.Clear();var points=new List<Point2>();foreach(var m in camp.Session.Definition.Markers)if(camp.Session.Active(m.Gate)&&camp.Session.Fits(m.Interaction,3))points.Add(m.Interaction);foreach(var room in camp.Session.Definition.Bedrooms)foreach(var p in room.Beds)if(camp.Session.Fits(p,3))points.Add(p);for(int i=0;i<count;i++)agents.Add(new Agent{P=points[i%points.Count],Goal=points[(i*7+3)%points.Count]});projectileCount=Math.Min(128,count*2);for(int i=0;i<projectileCount;i++)projectiles[i]=camp.Session.Definition.Marker("fire").Interaction;}
  void Simulate(double dt,int count,int frame){long t=System.Diagnostics.Stopwatch.GetTimestamp();double now=Time.realtimeSinceStartupAsDouble;foreach(var a in agents){if(!a.Queued&&(a.Path==null||frame%30==0)){a.Queued=true;a.Requested=now;requests.Enqueue(a);}if(a.Path!=null&&a.Cursor<a.Path.Count){var goal=a.Path[a.Cursor];double dx=goal.X-a.P.X,dy=goal.Y-a.P.Y,d=Math.Sqrt(dx*dx+dy*dy);if(d<.1)a.Cursor++;else a.P=camp.Session.Move(a.P,new Point2(dx/d*Math.Min(dt*3,d),dy/d*Math.Min(dt*3,d)),3);}}
   long navStart=System.Diagnostics.Stopwatch.GetTimestamp();int work=0;lastNavProcessed=0;while(requests.Count>0&&work++<4){var a=requests.Dequeue();a.Queued=false;latency=(now-a.Requested)*1000;a.Path=camp.Session.Route(a.P,a.Goal,3);a.Cursor=0;lastNavProcessed++;if(StreamingGeometry.Elapsed(navStart)>=1)break;}
   for(int i=0;i<projectileCount;i++){var p=projectiles[i];var step=new Point2(Math.Cos(i)*dt*10,Math.Sin(i)*dt*10);var q=camp.Session.Move(p,step,1);projectiles[i]=q.Equals(p)?camp.Session.Definition.Marker("fire").Interaction:q;}
   if(now>=nextStressEdit){nextStressEdit+=count>=64?.1:count>=32?.25:.5;editBatch.Clear();while(stressCursor<stressEarth.Count&&editBatch.Count<3){var cell=stressEarth[stressCursor++];if(camp.Session.Terrain.IsSolid(cell.X,cell.Y))editBatch.Add(cell);}if(editBatch.Count>0)camp.Session.DigPlayer(editBatch);}
   long discoveryStart=System.Diagnostics.Stopwatch.GetTimestamp();if(stressDiscovery!=null){var observer=agents[frame%agents.Count].P;stressDiscovery.ProcessChanges(observer);stressDiscovery.Explore(observer);stressDiscovery.Tick(dt);}discoveryMs=StreamingGeometry.Elapsed(discoveryStart);
   simMs=StreamingGeometry.Elapsed(t);
  }
  void Record(string phase,double interval){if(data.frames.Count>=30000)return;data.frames.Add(new Frame{navPending=requests.Count,navProcessed=lastNavProcessed,discovery=discoveryMs,discoveryKnown=stressDiscovery?.Remembered.Count??0,frame=Time.frameCount,counterFrame=Time.frameCount-1,phase=phase,interval=interval,main=telemetry.Main.Valid?telemetry.Main.LastValue*1e-6:-1,render=telemetry.Render.Valid?telemetry.Render.LastValue*1e-6:-1,gpu=telemetry.GpuMs(),allocation=telemetry.Allocation.Valid?telemetry.Allocation.LastValue:-1,nav=telemetry.Ms[(int)GeometryPhase.Navigation],navBytes=telemetry.AllocationCounterValid?telemetry.Bytes[(int)GeometryPhase.Navigation]:-1,navCalls=telemetry.Calls[(int)GeometryPhase.Navigation],construction=telemetry.Ms[(int)GeometryPhase.Construction],overlay=telemetry.Ms[(int)GeometryPhase.Overlay],display=camp.Live.DisplayMs,sim=simMs,navLatency=latency,resident=camp.Live.Stream.Resident.Count,pending=camp.Live.Stream.Pending,presentation=camp.Live.Stream.PendingPresentation,uploads=camp.Live.Gpu.TotalUploads,built=camp.Live.Stream.TotalBuilt,evicted=camp.Live.Stream.TotalEvicted,actors=agents.Count,projectiles=projectileCount,ready=camp.Live.Ready});}
  System.Collections.IEnumerator Settle(){int guard=0;do{yield return null;if(++guard>5000){Check(false,"Readiness timeout");yield break;}}while(!camp.Live.Ready||camp.Live.Stream.Pending>0||camp.Live.Stream.PendingPresentation>0);for(int i=0;i<4;i++)yield return null;}
  System.Collections.IEnumerator Capture(string name){yield return Settle();camp.CameraStudy.Capture(output,name);while(camp.CameraStudy.CapturePending)yield return null;camp.CameraStudy.captureLabel=false;}
  System.Collections.IEnumerator Snapshot(string name){bool complete=false,success=false;Unity.Profiling.Memory.MemoryProfiler.TakeSnapshot(Path.Combine(output,name+".snap"),(path,ok)=>{success=ok;complete=true;},Unity.Profiling.Memory.CaptureFlags.ManagedObjects|Unity.Profiling.Memory.CaptureFlags.NativeObjects|Unity.Profiling.Memory.CaptureFlags.NativeAllocations);double start=Time.realtimeSinceStartupAsDouble;while(!complete&&Time.realtimeSinceStartupAsDouble-start<60)yield return null;data.events.Add(new Event{frame=Time.frameCount,name="snapshot:"+name+(success?":success":":unavailable"),ms=(Time.realtimeSinceStartupAsDouble-start)*1000});}
  void MemorySample(string name){GC.Collect();long mesh=0,material=0;var meshes=Resources.FindObjectsOfTypeAll<Mesh>();var materials=Resources.FindObjectsOfTypeAll<Material>();foreach(var m in meshes)mesh+=Profiler.GetRuntimeMemorySizeLong(m);foreach(var m in materials)material+=Profiler.GetRuntimeMemorySizeLong(m);using(var process=System.Diagnostics.Process.GetCurrentProcess())data.memory.Add(new Memory{name=name,frame=Time.frameCount,managed=GC.GetTotalMemory(true),unity=Profiler.GetTotalAllocatedMemoryLong(),meshes=meshes.Length,materials=materials.Length,meshBytes=mesh,materialBytes=material,resident=camp.Live.Stream.Resident.Count,buffers=camp.Live.Gpu.BufferCount,processPrivate=process.PrivateMemorySize64,workingSet=process.WorkingSet64});}
  void EventScope(string name,long start)=>data.events.Add(new Event{frame=Time.frameCount,name=name,ms=StreamingGeometry.Elapsed(start)});
  void Check(bool ok,string label){data.checks.Add((ok?"PASS ":"FAIL ")+label);if(!ok)data.error+=label+";";}
